const root = document.getElementById("app");


  // ── 1. LIBRARY / SEARCH ─────────────────────────────────────────────────
export async function loadLibrary(){
    try{ const r=await api.get("/api/library"); S.library=r.charts||[]; if(S.screen==="library") go("library"); }
    catch(e){ S.library=[]; }
  }
  // ── l'accueil à deux univers (delta2 §8 / design 5a) ─────────────────────
  // Louis, 2026-08-08: « l'écran d'accueil devrait être + simpliste — on vire
  // le training mode et section cleanup, et je veux qu'il y ait 2 univers:
  // chercher une nouvelle chanson et consulter mes charts; pour mes charts je
  // peux créer des folders pour les trier; les chansons sont nommées
  // artiste / chanson. » L'accueil ne liste plus rien: deux portes et
  // Reprendre. La liste vit derrière la deuxième porte (renderCharts).

  // nommage artiste / chanson: le titre YouTube est sale (« (Official
  // Video) », « HD », « feat. »). Nettoyé à l'affichage SEULEMENT — jamais
  // dans le fichier, qui reste la clé. `artist` vient du serveur quand il l'a
  // (POST /api/chart-meta), sinon séparation sur le premier tiret.
export const _NOISE=/\s*[\(\[](official|lyric|audio|video|hd|4k|remaster\w*|live|mv)[^\)\]]*[\)\]]/ig;
export function chartName(c){
    if(c.artist) return {artist:c.artist, title:c.title||""};
    const t=(c.title||"").replace(_NOISE,"").trim();
    const m=t.match(/^(.{2,40}?)\s+[-–—]\s+(.+)$/);
    return m ? {artist:m[1].trim(), title:m[2].trim()} : {artist:"", title:t};
  }
  // « Artiste / Chanson »: artiste en gris, titre en encre. Une seule ligne,
  // ellipse à droite — jamais deux lignes, la liste doit se scanner.
export function nameEl(c, size){
    // Le TITRE passe avant l'artiste (UX #40, audit F1) : quand la place manque,
    // c'est l'artiste (flex-shrink énorme) qui rétrécit d'abord, le titre ne
    // se coupe qu'une fois l'artiste réduit à rien. Le « / » vit dans le span
    // de l'artiste : il disparaît avec lui, jamais de ligne qui commence par « / ».
    const n=chartName(c);
    const w=el("div",
      `font:600 ${size||16}px ${UI};color:${T.ink};display:flex;min-width:0;overflow:hidden;white-space:nowrap;`);
    if(n.artist){
      const a=el("span",`color:${T.faint};font-weight:500;flex:0 1000 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:pre;`,
        n.artist+" / ");
      a.dataset.nom="artiste"; w.appendChild(a);
    }
    const t=el("span","flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;", n.title);
    t.dataset.nom="titre"; w.appendChild(t);
    return w;
  }

  // Les dossiers vivent maintenant dans `../folders.js` : l'écran
  // d'analyse en a besoin aussi, et les laisser ici aurait fait un
  // cycle d'imports entre les deux écrans. On les ré-exporte pour ne
  // rien casser de ce qui les importait depuis ici.
export { FOLDERS_KEY, folderCount, fusionnerDossiersServeur, loadFolders,
         ranger, saveFolders } from "../folders.js";

// ── « Reprendre » dit aussi OÙ on s'était arrêté (UX #39, audit A1) ───────
// La position vit dans l'élément <audio> (audio.js, qu'on ne touche pas) : on
// l'écoute depuis le document, en CAPTURE — les évènements média ne remontent
// pas, mais ils descendent. Une écriture au plus toutes les 2 s en lecture,
// plus une à chaque pause. Rien n'est envoyé au serveur : c'est par appareil.
export const POS_KEY="harmPos:";
export function lirePosition(file){
    try{ const p=JSON.parse(localStorage.getItem(POS_KEY+file)||"null");
         return p && p.bar>1 ? p : null; }catch(e){ return null; }
  }
export function barreA(t){
    const ix=(S.barTimeIndex||[]).find(x=>t>=x.t0 && t<x.t1);
    return ix ? ix.bi : (S.playBar>=0 ? S.playBar : -1);
  }
let _posLast=0;
export function noterPosition(a, force){
    try{
      const f=S.model && S.model.file; if(!f || !a) return;
      const now=Date.now(); if(!force && now-_posLast<2000) return;
      _posLast=now;
      const t=a.currentTime||0;
      if(a.ended || (a.duration && t>a.duration-1)){ localStorage.removeItem(POS_KEY+f); return; }
      const bi=barreA(t); if(t<1 || bi<0) return;
      localStorage.setItem(POS_KEY+f, JSON.stringify({t:Math.round(t*10)/10, bar:bi+1}));
    }catch(e){}
  }
S._notePos=noterPosition;   // branché sur S.audio par audio.js (l'élément n'est pas dans le DOM)
if(typeof document!=="undefined" && !window.__harmPosInstalle){
    window.__harmPosInstalle=true;
    document.addEventListener("timeupdate",e=>{ if(e.target && e.target.tagName==="AUDIO" && !e.target.paused) noterPosition(e.target,false); },true);
    document.addEventListener("pause",e=>{ if(e.target && e.target.tagName==="AUDIO") noterPosition(e.target,true); },true);
    document.addEventListener("ended",e=>{ if(e.target && e.target.tagName==="AUDIO") noterPosition(e.target,true); },true);
  }

export function renderLibrary(){
    resetSpelling();
    S.folders=loadFolders();
    // une seule fois par session : on récupère ce que le serveur sait des
    // dossiers, puis on redessine SI ça change quelque chose.
    if(!S._dossiersFusionnes){
      S._dossiersFusionnes=true;
      fusionnerDossiersServeur().then(bouge=>{
        if(bouge && S.screen==="library") go("library",{push:false});
      });
    }
    const w=screenWrap();

    const head=el("div",`flex:0 0 auto;padding:calc(14px + env(safe-area-inset-top)) 20px 22px;`);
    const logo=el("div",`font:italic 600 30px ${SERIF};color:${T.ink};`);
    logo.innerHTML='harmon<span style="color:'+T.accent+'">ia</span>';
    head.appendChild(logo);
    head.appendChild(el("div",`font:italic 14px ${SERIF};color:${T.faint};margin-top:3px;`,
      "l'harmonie de n'importe quelle chanson"));
    w.appendChild(head);

    const body=el("div",
      `flex:1;min-height:0;overflow-y:auto;padding:0 20px;display:flex;flex-direction:column;gap:14px;`);
    body.className="ap-scroll";

    // reprendre — statistiquement le premier geste. Le dernier chart OUVERT
    // (harmLastChart, comme l'ancien Continue), pas le premier de la liste.
    const lastFile=(()=>{ try{return localStorage.getItem("harmLastChart");}catch(e){return null;} })();
    const last=(lastFile && S.library.find(c=>c.file===lastFile))
      || [...S.library].sort((a,b)=>b.mtime-a.mtime)[0];
    if(last){
      const cont=el("div",
        `background:${T.card};border:1px solid ${T.line};border-radius:18px;padding:14px 16px;`+
        `display:flex;align-items:center;gap:14px;cursor:pointer;`);
      const ct=el("div","flex:1;min-width:0;");
      ct.appendChild(el("div",
        `font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.accent};`,"Reprendre"));
      const nm=nameEl(last,16); nm.style.marginTop="3px"; ct.appendChild(nm);
      const pos=lirePosition(last.file);
      if(pos){
        const ou=el("div",`font:500 12.5px ${UI};color:${T.faint};margin-top:3px;`,"mesure "+pos.bar);
        ou.dataset.reprise="mesure"; ct.appendChild(ou);
      }
      cont.appendChild(ct);
      cont.appendChild(el("span",`flex:0 0 auto;font:400 24px ${UI};color:${T.rule};`,"›"));
      // La carte dit « mesure 42 » : elle doit aussi y RAMENER (vérif. 2026-10-01 —
      // elle ouvrait le chart au début). audio.js consomme S._resumeAt dès que
      // l'élément connaît sa durée.
      cont.onclick=()=>{ S._resumeAt=pos?{f:last.file,t:pos.t}:null; openChart(last.file); };
      body.appendChild(cont);
    }
    // porte 1 — chercher. Le champ est DANS la carte: on ne fait pas taper
    // l'utilisateur sur un écran pour l'emmener sur un autre où il retape.
    const seek=el("div",
      `background:${T.card};border:1.5px solid ${T.accent};border-radius:20px;padding:18px 18px 16px;`);
    seek.appendChild(el("div",
      `font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.accent};`,"Chercher"));
    seek.appendChild(el("div",`font:600 22px ${UI};margin-top:6px;`,"Une nouvelle chanson"));
    const sfield=el("div",
      `margin-top:14px;height:52px;border-radius:14px;background:${T.paper};`+
      `border:1px solid ${T.line};display:flex;align-items:center;gap:10px;padding:0 16px;`);
    sfield.appendChild(el("span",`font:400 17px ${UI};color:${T.rule};`,"⌕"));
    const sinp=el("input",
      `flex:1;min-width:0;height:100%;border:none;background:none;outline:none;font:500 15px ${UI};color:${T.ink};`);
    sinp.type="text";
    sinp.placeholder="Titre, artiste ou lien YouTube";
    sinp.setAttribute("enterkeyhint","search");
    sinp.onkeydown=e=>{
      if(e.key!=="Enter" || !sinp.value.trim()) return;
      const q=sinp.value.trim(); sinp.blur();
      S.searchQuery=q; S.results=[]; go("search"); runSearch(q);
    };
    sfield.appendChild(sinp);
    seek.appendChild(sfield);
    // importer un fichier audio : un lien discret, pas une 4e carte
    const fin=document.createElement("input");
    fin.type="file"; fin.accept="audio/*,.mp3,.m4a,.wav,.flac,.ogg,.aac"; fin.style.display="none";
    fin.onchange=()=>{ const f=fin.files&&fin.files[0]; if(f) startFileImport(f); };
    seek.appendChild(fin);
    const imp=el("div",`font:600 13.5px ${UI};color:${T.accent};margin-top:12px;cursor:pointer;min-height:${SZ.control}px;display:flex;align-items:center;`,
      "Importer un fichier audio");
    imp.onclick=()=>fin.click();
    seek.appendChild(imp);
    seek.appendChild(el("div",`font:italic 12.5px ${SERIF};color:${T.faint};`,
      "jusqu’à "+LIMITE_IMPORT.min+" min et "+LIMITE_IMPORT.mo+" Mo"));
    body.appendChild(seek);

    // porte 2 — mes charts
    const mine=el("div",
      `background:${T.card};border:1px solid ${T.line};border-radius:20px;padding:18px;`+
      `display:flex;align-items:center;gap:14px;cursor:pointer;`);
    const mt=el("div","flex:1;min-width:0;");
    mt.appendChild(el("div",
      `font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};`,"Consulter"));
    mt.appendChild(el("div",`font:600 22px ${UI};margin-top:6px;`,"Mes charts"));
    const nf=(S.folders.order||[]).length;
    mt.appendChild(el("div",`font:italic 13.5px/1.5 ${SERIF};color:${T.faint};margin-top:5px;`,
      S.library.length+" chanson"+(S.library.length>1?"s":"")+(nf?(" · "+nf+" dossier"+(nf>1?"s":"")):"")));
    mine.appendChild(mt);
    mine.appendChild(el("span",`flex:0 0 auto;font:400 26px ${UI};color:${T.rule};`,"›"));
    mine.onclick=()=>go("charts");
    body.appendChild(mine);

    w.appendChild(body);

    const foot=el("div",
      `flex:0 0 auto;padding:16px 20px calc(18px + env(safe-area-inset-bottom));display:flex;gap:10px;`);
    // Enregistrer et Jam sont BRANCHÉS depuis le 2026-08-20 : le serveur sert
    // /api/record-analyze et /api/jam/start|chunk|stop (harmonia_min/server.py),
    // et l'adresse https rend le micro accessible depuis le téléphone. Ils
    // restent gris (`state:"off"`) tant qu'on est sur une adresse http : le
    // navigateur n'y donne AUCUN accès au micro, et un bouton qui ouvre un
    // écran où REC ne peut pas marcher est pire qu'un bouton qui explique.
    const micOK=micDispo();
    const versHttps=()=>toast("Le micro demande une adresse https — ouvre "
                              +HTTPS_HOST+" (même app, même bibliothèque).");
    foot.appendChild(kitButton("Enregistrer",
                               micOK?()=>go("record"):versHttps,
                               {height:52, grow:true, state:micOK?"on":"off"}));
    foot.appendChild(kitButton("Jam",
                               micOK?()=>go("jam"):versHttps,
                               {height:52, grow:true, state:micOK?"on":"off"}));
    w.appendChild(foot);
    return w;
  }

  // ── MES CHARTS (delta2 §8): filtre, dossiers avec compteur, hors dossier ─
export function renderCharts(){
    resetSpelling();
    S.folders=S.folders||loadFolders();
    const w=screenWrap();
    const open=S.openFolder||null;          // null = racine

    const bar=el("div",
      `flex:0 0 auto;display:flex;align-items:center;gap:12px;`+
      `padding:calc(6px + env(safe-area-inset-top)) 14px 10px;`);
    bar.appendChild(kitIcon("‹", ()=>{ if(open){ S.openFolder=null; go("charts",{push:false}); } else go("library"); }, "Retour"));
    bar.appendChild(el("div",`flex:1;min-width:0;font:italic 600 20px ${SERIF};color:${T.ink};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`,
      open||"Mes charts"));
    bar.appendChild(kitButton(S.libraryEdit?"OK":"Modifier",
      ()=>{ S.libraryEdit=!S.libraryEdit; go("charts",{push:false}); },
      {state:S.libraryEdit?"on":"off"}));
    w.appendChild(bar);

    const filt=el("div",`flex:0 0 auto;padding:0 14px 14px;`);
    const fb=el("div",
      `height:48px;border-radius:14px;background:${T.card};border:1px solid ${T.line};`+
      `display:flex;align-items:center;gap:10px;padding:0 14px;`);
    fb.appendChild(el("span",`font:400 16px ${UI};color:${T.rule};`,"⌕"));
    const fi=el("input",
      `flex:1;min-width:0;height:100%;min-height:${SZ.control}px;border:none;background:none;outline:none;font:500 14px ${UI};color:${T.ink};`);
    fi.placeholder="Filtrer mes charts"; fi.value=S.chartFilter||"";
    fi.oninput=()=>{ S.chartFilter=fi.value; paintChartList(); };
    fb.appendChild(fi); filt.appendChild(fb);
    // Tri visible (audit F2) : `S.librarySort` existait sans écran qui le lise.
    const tri=el("div",`display:flex;align-items:center;gap:6px;margin-top:8px;`);
    tri.appendChild(el("span",`font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};margin-right:4px;`,"Trier"));
    [["recent","Récents"],["az","A–Z"]].forEach(([k,lab])=>{
      const b=kitButton(lab, ()=>{
        S.librarySort=k;
        try{ localStorage.setItem("harmLibrarySort",k); }catch(e){}
        go("charts",{push:false});
      }, {state:(S.librarySort||"recent")===k?"on":"off"});
      b.dataset.tri=k; tri.appendChild(b);
    });
    filt.appendChild(tri); w.appendChild(filt);

    const body=el("div",`flex:1;min-height:0;overflow-y:auto;padding:0 14px calc(20px + env(safe-area-inset-bottom));`);
    body.className="ap-scroll"; w.appendChild(body);
    S._chartBody=body;
    paintChartList();
    return w;
  }
export function paintChartList(){
    const body=S._chartBody; if(!body) return;
    clear(body);
    const F=S.folders, open=S.openFolder||null;
    const q=(S.chartFilter||"").trim();

    function sectionHead(label, action, onAction){
      const h=el("div","display:flex;align-items:center;justify-content:space-between;margin:2px 4px 9px;");
      h.appendChild(el("span",
        `font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};`,label));
      if(action){
        const b=el("button",
          `border:none;background:none;padding:12px 4px;margin:-12px -4px;min-height:${SZ.control}px;min-width:${SZ.control}px;`+
          `font:600 13px ${UI};color:${T.accent};cursor:pointer;`, action);
        b.onclick=onAction; h.appendChild(b);
      }
      return h;
    }

    // Recherche GLOBALE (2026-10-01, docs/STATE.md « La bibliothèque ») : dès
    // qu'il y a du texte, on cherche dans tous les dossiers, où qu'on soit ;
    // chaque résultat dit en petit gris où il vit. Vider le champ ramène au
    // dossier ouvert — `S.openFolder` n'est jamais touché ici.
    if(q){
      const res=chercherPartout(trierCharts(S.library), F.of, q, chartName);
      const n=res.length;
      body.appendChild(sectionHead(n ? (n+" chart"+(n>1?"s":"")+" · tous les dossiers")
                                     : "Tous les dossiers"));
      if(n) body.appendChild(chartRows(res.map(r=>r.chart), res.map(r=>r.dossier)));
      else body.appendChild(el("div",
        `font:italic 13px/1.6 ${SERIF};color:${T.faint};padding:0 4px 4px;`,
        "rien ne correspond à « "+q+" »"));
      return;
    }
    if(!open){
      body.appendChild(sectionHead("Dossiers"));
      const list=el("div","display:flex;flex-direction:column;gap:8px;");
      (F.order||[]).forEach(name=>{
        const row=el("div",
          `height:60px;border-radius:14px;background:${T.card};border:1px solid ${T.line};`+
          `display:flex;align-items:center;gap:13px;padding:0 14px;cursor:pointer;`);
        row.appendChild(folderMark(name===(F.order||[])[0]));
        const tx=el("div","flex:1;min-width:0;");
        tx.appendChild(el("div",`font:600 16px ${UI};color:${T.ink};`,name));
        const n=folderCount(name);
        tx.appendChild(el("div",`font:500 12.5px ${UI};color:${T.faint};margin-top:2px;`,
          n+" chanson"+(n>1?"s":"")));
        row.appendChild(tx);
        row.appendChild(el("span",`flex:0 0 auto;font:400 22px ${UI};color:${T.rule};`,"›"));
        row.onclick=()=>{ S.openFolder=name; go("charts",{push:false}); };
        list.appendChild(row);
      });
      if(!(F.order||[]).length) list.appendChild(el("div",
        `font:italic 13px/1.6 ${SERIF};color:${T.faint};padding:0 4px 4px;`,
        "aucun dossier — crées-en un pour ranger tes charts"));
      body.appendChild(list);
      // un vrai bouton (UX #41, audit F3) : « Nouveau » en rouge n'avait pas
      // l'air tapable.
      const nv=kitButton("＋ Nouveau dossier", ()=>promptNewFolder(), {height:SZ.control, state:"on"});
      nv.style.width="100%"; nv.style.marginTop="10px"; nv.style.marginBottom="18px";
      nv.dataset.act="nouveau-dossier"; body.appendChild(nv);
      body.appendChild(sectionHead("Hors dossier"));
      body.appendChild(chartRows(trierCharts(S.library.filter(c=>!F.of[c.file]))));
    } else {
      body.appendChild(chartRows(trierCharts(S.library.filter(c=>F.of[c.file]===open))));
    }
  }

  // la petite forme de dossier — un rectangle et son onglet, pas une icône
  // importée: deux divs, ça tient dans le système
export function folderMark(accent){
    const col=accent?T.accent:T.rule;
    const d=el("div",
      `flex:0 0 auto;width:34px;height:28px;border:1.5px solid ${col};`+
      `border-radius:4px 6px 6px 6px;position:relative;`+
      `background:${accent?"rgba(138,43,43,.07)":T.paper};`);
    d.appendChild(el("div",
      `position:absolute;top:-4.5px;left:-1.5px;width:15px;height:5px;`+
      `background:${col};border-radius:2px 2px 0 0;`));
    return d;
  }
// Tri de la liste : récents = date du fichier décroissante, A–Z = titre.
export function trierCharts(items){
    const a=items.slice();
    if((S.librarySort||"recent")==="az")
      a.sort((x,y)=>(chartName(x).title||"").localeCompare(chartName(y).title||"","fr",{sensitivity:"base"}));
    else a.sort((x,y)=>(y.mtime||0)-(x.mtime||0));
    return a;
  }
export function chartRows(items, dossiers){
    const list=el("div","display:flex;flex-direction:column;gap:8px;");
    items.forEach((c,i)=>{
      const row=el("div",
        `min-height:64px;border-radius:14px;background:${T.card};border:1px solid ${T.line};`+
        `display:flex;align-items:center;gap:12px;padding:10px 14px;cursor:pointer;`);
      const tx=el("div","flex:1;min-width:0;");
      tx.appendChild(nameEl(c,16));
      tx.appendChild(el("div",`font:500 12.5px ${UI};color:${T.faint};margin-top:3px;`,
        note(c.key.tonic)+" "+(c.key.mode==="minor"?"mineur":c.key.mode==="major"?"majeur":c.key.mode)+
        " · "+c.bars+" mesures"+(c.hasAudio?"":" · sans audio")));
      if(c.corrected){
        const pa=el("span",
          `display:inline-block;margin-left:8px;padding:1px 7px;border-radius:9px;font:600 11px ${UI};`+
          `color:${T.accent};border:1px solid ${T.accent};vertical-align:1px;`,"✓ corrigé");
        pa.dataset.pastille="corrige"; tx.children[1].appendChild(pa);
      }
      // en recherche globale : le dossier où vit le chart, discret
      if(dossiers && dossiers[i]) tx.appendChild(el("div",
        `font:italic 12px ${SERIF};color:${T.faint};margin-top:2px;`+
        `white-space:nowrap;overflow:hidden;text-overflow:ellipsis;`,
        "▸ "+dossiers[i]));
      row.appendChild(tx);
      if(S.libraryEdit){
        row.appendChild(kitButton("Ranger", e=>{ e.stopPropagation(); openMoveSheet(c); }, {small:true}));
        // la suppression vivait dans l'ancien Edit — elle reste (même undo-
        // snackbar), le delta2 ne la remplaçait par rien
        row.appendChild(kitIcon("×", e=>{ e.stopPropagation(); deleteChart(c); }, "Supprimer "+c.title));
        // en Modifier, la ligne édite artiste/titre (« le titre YouTube ment
        // souvent » — delta2 §8, champ éditable côté client)
        row.onclick=()=>openMetaSheet(c);
      } else {
        row.appendChild(el("span",`flex:0 0 auto;font:400 22px ${UI};color:${T.rule};`,"›"));
        row.onclick=()=>openChart(c.file);
      }
      list.appendChild(row);
    });
    return list;
  }

  // « Ranger »: une feuille avec les dossiers + Nouveau + Retirer. Un seul
  // dossier possible, donc c'est un choix, pas des cases à cocher.
export function openMoveSheet(c){
    const back=overlay(), sheet=sheetBox(); sheet.appendChild(handle());
    sheet.appendChild(el("div",
      `font:600 11px ${UI};letter-spacing:.06em;text-transform:uppercase;color:${T.faint};margin-bottom:6px;`,
      "Ranger dans"));
    sheet.appendChild(nameEl(c,17));
    const list=el("div","display:flex;flex-direction:column;gap:8px;margin-top:16px;");
    (S.folders.order||[]).forEach(name=>{
      const on=S.folders.of[c.file]===name;
      const b=kitButton(name, ()=>{
        S.folders.of[c.file]=name; saveFolders(S.folders);
        closeOverlay(back); paintChartList();
      }, {height:52, state:on?"on":"off"});
      b.style.width="100%";
      list.appendChild(b);
    });
    const nb=kitButton("Nouveau dossier…", ()=>{
      closeOverlay(back); promptNewFolder(c);
    }, {height:52});
    nb.style.width="100%"; list.appendChild(nb);
    if(S.folders.of[c.file]){
      const rb=kitButton("Retirer du dossier", ()=>{
        delete S.folders.of[c.file]; saveFolders(S.folders);
        closeOverlay(back); paintChartList();
      }, {height:52});
      rb.style.width="100%"; list.appendChild(rb);
    }
    sheet.appendChild(list);
    back.appendChild(sheet); root.appendChild(back);
  }

  // Saisie du nom: champ dans une feuille, pas un prompt() — le prompt de
  // l'OS casse l'identité papier/bordeaux (même raison qu'au confirm() de
  // suppression, 2026-07-20).
export function promptNewFolder(alsoMove){
    const back=overlay(), sheet=sheetBox(); sheet.appendChild(handle());
    sheet.appendChild(el("div",`font:600 17px ${UI};color:${T.ink};margin-bottom:12px;`,"Nouveau dossier"));
    const inp=el("input",
      `width:100%;height:52px;border-radius:14px;border:1px solid ${T.line};background:${T.paper};`+
      `padding:0 14px;font:500 16px ${UI};color:${T.ink};outline:none;box-sizing:border-box;`);
    inp.placeholder="Standards";
    sheet.appendChild(inp);
    const row=el("div","display:flex;gap:10px;margin-top:14px;");
    row.appendChild(kitButton("Annuler", ()=>closeOverlay(back), {height:52, grow:true}));
    row.appendChild(kitButton("Créer", ()=>{
      const name=(inp.value||"").trim(); if(!name) return;
      S.folders.order=S.folders.order||[];
      if(S.folders.order.indexOf(name)<0) S.folders.order.push(name);
      if(alsoMove) S.folders.of[alsoMove.file]=name;
      saveFolders(S.folders); closeOverlay(back); paintChartList();
    }, {height:52, grow:true, state:"on"}));
    sheet.appendChild(row);
    back.appendChild(sheet); root.appendChild(back);
    setTimeout(()=>inp.focus(),80);
  }

  // « le titre YouTube ment souvent » (delta2 §8): artiste/titre éditables
  // côté client — POST /api/chart-meta/<file>, ressert par /api/library.
export function openMetaSheet(c){
    const back=overlay(), sheet=sheetBox(); sheet.appendChild(handle());
    sheet.appendChild(el("div",`font:600 17px ${UI};color:${T.ink};margin-bottom:12px;`,"Artiste / Chanson"));
    const n=chartName(c);
    const mk=(ph,val)=>{ const i=el("input",
      `width:100%;height:52px;border-radius:14px;border:1px solid ${T.line};background:${T.paper};`+
      `padding:0 14px;font:500 16px ${UI};color:${T.ink};outline:none;box-sizing:border-box;`);
      i.placeholder=ph; i.value=val||""; return i; };
    const ia=mk("Artiste", c.artist||n.artist);
    const it=mk("Chanson", c.artist?(c.title||""):n.title);
    ia.style.marginBottom="10px";
    sheet.appendChild(ia); sheet.appendChild(it);
    const row=el("div","display:flex;gap:10px;margin-top:14px;");
    row.appendChild(kitButton("Annuler", ()=>closeOverlay(back), {height:52, grow:true}));
    row.appendChild(kitButton("Enregistrer", ()=>{
      const artist=(ia.value||"").trim(), title=(it.value||"").trim();
      c.artist=artist; if(title) c.title=title;
      api.post("/api/chart-meta/"+c.file,{artist,title:c.title}).catch(()=>{});
      closeOverlay(back); paintChartList();
    }, {height:52, grow:true, state:"on"}));
    sheet.appendChild(row);
    back.appendChild(sheet); root.appendChild(back);
  }
  // Undo-snackbar delete (2026-07-20): a blocking confirm() used the OS's own
  // dialog chrome, breaking the app's paper/maroon identity, and offers no
  // way back if you tap it by mistake. Optimistic remove + a few seconds to
  // undo is the standard, gentler mobile pattern — the actual server DELETE
  // only fires once the window lapses.
export function showUndoSnackbar(msg, onUndo, opts){
    opts=opts||{};
    if(S._undoBox) S._undoBox.remove();
    const box=el("div",`position:absolute;left:16px;right:16px;bottom:calc(100px + env(safe-area-inset-bottom));z-index:70;display:flex;align-items:center;justify-content:space-between;gap:14px;background:${T.deep};color:#fff;font:600 13px ${UI};padding:12px 12px 12px 16px;border-radius:14px;box-shadow:0 10px 26px -10px rgba(0,0,0,.5);animation:ap-in .25s both;`);
    box.appendChild(el("div","flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;",msg));
    const undoBtn=el("button",`flex:0 0 auto;border:none;background:transparent;color:${T.amber||"#c58a2e"};font:700 13px ${UI};cursor:pointer;padding:6px 4px;`,opts.label||"Annuler");
    undoBtn.onclick=()=>{ clearTimeout(box._t); box.remove(); S._undoBox=null; onUndo(); };
    box.appendChild(undoBtn);
    root.appendChild(box); S._undoBox=box;
    box._t=setTimeout(()=>{ box.style.opacity="0"; box.style.transition="opacity .3s"; setTimeout(()=>{ box.remove(); if(S._undoBox===box) S._undoBox=null; },300); },opts.ms||5000);
  }
export function deleteChart(r){
    S.library=S.library.filter(x=>x.file!==r.file);
    // depuis Mes charts (delta2 §8) on reste sur place — la ligne disparaît
    // aussi de son dossier toute seule (le filtre roule sur S.library)
    if(S.screen==="charts") paintChartList(); else go("library",{push:false});
    const t=setTimeout(()=>{ api.del("/api/chart/"+r.file).catch(()=>{}); },5000);
    showUndoSnackbar(`Supprimé « ${r.title} »`, ()=>{
      clearTimeout(t);
      S.library.push(r);
      if(S.screen==="charts") paintChartList(); else go("library",{push:false});
    });
  }
export const STATUS_LABEL={corrected:"corrected",analyzed:"analysed",new:"not started"};
export const STATUS_COLOR=k=>({corrected:T.green,analyzed:T.accent,new:T.faint}[k]||T.faint);

